2	 * Comment creation, edit window enforcement, mention extraction and soft delete.
3	 *
4	 * Must call (do not reimplement): assertCan, assertOrgScope, emit, archivePatch, consumeRateLimit
5	 */
6	import { emit } from "@/lib/event-bus";
7	import { resolveMentions } from "@/lib/mentions";
8	import { assertCan } from "@/lib/permissions";
9	import { consumeRateLimit } from "@/lib/rate-limit";
10	import { archivePatch, assertNotArchived } from "@/lib/soft-delete";
11	import { assertOrgScope } from "@/lib/tenant";
12	import * as commentRepo from "@/server/repositories/comment-repository";
13	import * as issueRepo from "@/server/repositories/issue-repository";
14	import * as memberRepo from "@/server/repositories/member-repository";
15	import {
16	  actorEnvelope,
17	  commentResource,
18	  issueResource,
19	  requireFound,
20	} from "./_support";
21	import type {
22	  CreateCommentInput,
23	  DeleteCommentInput,
24	  UpdateCommentInput,
25	} from "@/schemas/comment";
26	import type { Comment, CommentThreadNode } from "@/types/comment";
27	import type { IssueId, OrgId, UserId } from "@/types/common";
28	import type { Actor } from "@/types/member";
29	
30	/** How long after posting an author may still edit their own comment. */
31	const EDIT_WINDOW_MS = 15 * 60 * 1000;
32	
33	/** How many members are scanned when resolving `@handle` mentions. */
34	const MENTION_LOOKUP_LIMIT = 100;
35	
36	/** Token bucket protecting the comment thread from burst posting. */
37	const COMMENT_CREATE_BUCKET = "comment:create";
38	
39	/**
40	 * Posts a comment on a live issue. Mentions written as `@handle` in the body
41	 * are resolved against the org's members here, so the stored row and the
42	 * `comment.created` payload agree on who was mentioned — the notification
43	 * fan-out reads that list rather than re-parsing the markdown.
44	 */
45	export async function createComment(
46	  actor: Actor,
