37	 * no notification logic: it announces the fact, and whoever cares (in-app
38	 * alerts, the digest, webhooks) reacts on the bus.
39	 */
40	export async function runOverdueIssueJob(now: Date): Promise<JobResult> {
41	  return runJob("overdue-issues", async (result) => {
42	    if (!shouldFilterArchived(LIVE_ONLY)) {
43	      logger.warn("archive scope misconfigured; skipping sweep", {});
44	      return;
45	    }
46	
47	    const stamp = toIsoTimestamp(now);
48	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
49	
50	    for (const orgId of orgIds) {
51	      const overdue = await issueRepo.listOverdueIssues(orgId, stamp);
52	
53	      for (const issue of overdue) {
54	        if (issue.dueAt === null) continue;
55	        if (reported.has(issue.id)) continue;
56	
57	        try {
58	          await emit("issue.overdue", {
59	            orgId,
60	            actorId: null,
61	            occurredAt: stamp,
62	            issueId: issue.id,
63	            projectId: issue.projectId,
64	            dueAt: issue.dueAt,
65	            assigneeId: issue.assigneeId,
66	          });
67	          reported.add(issue.id);
68	          result.processed += 1;
69	        } catch (error) {
70	          result.failed += 1;
71	          logger.error("failed to announce overdue issue", {
72	            issueId: issue.id,
73	            reason: error instanceof Error ? error.message : String(error),
74	          });
75	        }
76	      }
77	    }
78	  });
