/**
 * While a project is archived, its issues and everything attached to them
 * (fields, status, assignment, comments, attachments) are read-only, even if
 * the issue itself was never individually archived.
 */
export async function assertIssueProjectNotArchived(
  orgId: OrgId,
  projectId: ProjectId,
  issueId: IssueId,
): Promise<void> {
  const project = await projectRepo.findProjectById(orgId, projectId);
  if (project !== null && isArchived(project)) {
    throw new AlreadyArchivedError("Issue", issueId);
  }
}

